package com.nora.tunnel.data.repository import com.nora.tunnel.data.database.* import kotlinx.coroutines.flow.Flow class HistoryRepository(private val dao: HistoryDao) { fun observe(): Flow<List<ConnectionSession>> = dao.observeAll() suspend fun insert(session: ConnectionSession) = dao.insert(session) suspend fun clear() = dao.clear() // Never store passwords/private keys } @Dao interface HistoryDao { @Query("SELECT * FROM ConnectionSession ORDER BY startTime DESC") fun observeAll(): Flow<List<ConnectionSession>> @Insert suspend fun insert(s: ConnectionSession) @Query("DELETE FROM ConnectionSession") suspend fun clear() }
